{
  "technical_and_design_decisions": [
    "Externalize reusable Go components into versioned libraries, using fabric-protos-go for generated protocol types and fabric-lib-go or equivalent libraries for shared utilities.",
    "Preserve the existing public APIs and behavior of protoutil, BCCSP, MSP, and the discovery client wherever practical, minimizing downstream migration changes.",
    "Refactor statebased so its only Hyperledger Fabric imports are protocol packages; replace direct cauthdsl, protoutil, identity, and related imports with narrowly scoped local or external-library abstractions.",
    "Refactor entities packages to remove Fabric implementation dependencies, including logging and BCCSP dependencies, while retaining required functional behavior.",
    "Use Go modules, explicit dependency versions, and dependency-graph checks in CI to enforce the stated import constraints.",
    "Move or copy implementations into independently consumable repositories, then update Fabric and SDK consumers to depend on the externalized packages rather than maintaining modified internal copies.",
    "Retain backward-compatible wrapper APIs where feasible and document any unavoidable breaking changes with migration guidance.",
    "Correct the marbles02_private sample instructions by adding the required newline-stripping command to the affected environment-variable examples."
  ],
  "assumptions": [
    "The work includes implementation, tests, dependency updates, documentation, and CI changes for all user stories U1 through U8.",
    "The existing Fabric and Fabric Go SDK source trees are available, buildable, and sufficiently similar to the versions described by the specification.",
    "External repositories or modules can be created or modified as part of the increment; repository administration, legal review, and release management outside the code changes are excluded.",
    "Generated protobuf code is consumed from fabric-protos-go and does not need to be redesigned, except for regeneration or version updates required by the refactoring.",
    "The desired result is source-level and behavioral compatibility, not a redesign of cryptographic, MSP, discovery, or protobuf semantics.",
    "The developer is responsible for resolving ordinary dependency, module, import-cycle, and platform compatibility issues, including Linux-based CI and the documented Windows/Ubuntu sample usage.",
    "Security audits, performance benchmarking at production scale, and migration of every external third-party consumer are excluded; representative compatibility tests are included.",
    "Estimates are work-hours for one developer and include normal code review preparation but not elapsed waiting time for external approvals."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository and dependency baseline",
      "activity_description": "Inspect the Fabric and SDK copies, identify package ownership and duplicated implementations, run existing tests and go list dependency reports, and record current APIs, module versions, and dependency constraints.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalization architecture and migration design",
      "activity_description": "Define target repositories or modules, package boundaries, versioning strategy, compatibility approach, dependency direction, protobuf usage, and migration sequencing for protoutil, BCCSP, MSP, and discovery.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "Statebased dependency decoupling",
      "activity_description": "Refactor the statebased package to remove fabric/comm, fabric/protoutil, pkg/errors, cauthdsl, identity, and other non-protobuf Fabric dependencies; introduce minimal replacement abstractions or external-library calls and update unit tests.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A4",
      "activity_name": "Entities dependency decoupling",
      "activity_description": "Remove Fabric implementation dependencies from the entities packages, including BCCSP and logging transitive dependencies, while preserving behavior and adding or updating package-level tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A5",
      "activity_name": "Protoutil externalization",
      "activity_description": "Extract reusable protoutil code into the selected external library, adapt imports to fabric-protos-go, resolve package and dependency issues, preserve supported APIs, and add comprehensive unit and compatibility tests.",
      "most_likely_effort": 100
    },
    {
      "activity_id": "A6",
      "activity_name": "BCCSP externalization",
      "activity_description": "Extract the BCCSP interfaces, factories, software implementation, utilities, and required supporting packages from Fabric and the SDK copy; remove SDK-specific modifications where possible, update consumers, and test cryptographic behavior and compatibility.",
      "most_likely_effort": 120
    },
    {
      "activity_id": "A7",
      "activity_name": "MSP externalization",
      "activity_description": "Externalize MSP code from the Fabric and SDK copies, reconcile API and implementation differences, update dependencies and consumers, preserve identity and certificate behavior, and add unit and integration coverage.",
      "most_likely_effort": 140
    },
    {
      "activity_id": "A8",
      "activity_name": "Discovery client externalization",
      "activity_description": "Extract the discovery client from the SDK copy into the external library, reconcile modified code and APIs, update protobuf and transport dependencies, migrate SDK usage, and test request, response, and error behavior.",
      "most_likely_effort": 100
    },
    {
      "activity_id": "A9",
      "activity_name": "Fabric and SDK consumer migration",
      "activity_description": "Replace internal and Fabric-local imports with external module imports, update go.mod and dependency locks, remove obsolete duplicate code, resolve import cycles and compatibility issues, and update affected build scripts.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A10",
      "activity_name": "Marbles02_private documentation correction",
      "activity_description": "Update both affected fabric-samples tutorial sections and shell examples with the tr -d newline guidance, verify the commands in the documented Ubuntu/Windows-hosted environment scenario, and clarify the JSON parsing failure.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "Dependency, regression, and compatibility testing",
      "activity_description": "Add dependency-graph assertions for statebased and entities, run package and integration tests across Fabric and SDK consumers, test externalized APIs, verify cryptographic and identity regressions, and diagnose and fix failures.",
      "most_likely_effort": 100
    },
    {
      "activity_id": "A12",
      "activity_name": "CI, build, and release documentation updates",
      "activity_description": "Update CI workflows, module checks, generated or vendored dependency handling, linting, release metadata, package documentation, examples, and migration notes for the newly externalized libraries.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A13",
      "activity_name": "Final integration and delivery hardening",
      "activity_description": "Perform full clean-build verification, review public API and dependency boundaries, run final regression checks, clean obsolete files and comments, and prepare the implementation for merge and release.",
      "most_likely_effort": 40
    }
  ],
  "reported_total": {
    "most_likely_effort": 864
  }
}

